78	/// Given a range, writes comments contained within the range. This function
79	/// removes comments that are written here from the [CommentMap] for later use.
80	///
81	/// Most comment formatting should be done using [rewrite_with_comments] in
82	/// the context of the AST, but in some cases (eg. at the end of module) we require this function.
83	///
84	/// Returns:
85	/// `Ok(true)` on successful execution with comments written,
86	/// `Ok(false)` on successful execution and if there are no comments within the given range,
87	/// `Err` if a FormatterError was encountered.
88	///
89	/// The `range` can be an empty [Range], or have its start being greater then its end.
90	/// This is to support formatting arbitrary lexed trees, that are not necessarily backed by source code.
91	pub fn write_comments(
92	    formatted_code: &mut FormattedCode,
93	    range: Range<usize>,
94	    formatter: &mut Formatter,
95	) -> Result<bool, FormatterError> {
96	    {
97	        let mut comments_iter = formatter
98	            .comments_context
99	            .map
100	            .comments_between(&range)
101	            .peekable();
102	
103	        if comments_iter.peek().is_none() {
104	            return Ok(false);
105	        };
106	
107	        // If the already formatted code ends with some pattern and doesn't already end with a newline,
108	        // we want to add a newline here.
109	        if formatted_code.ends_with(['{', '}']) && !formatted_code.ends_with('\n') {
110	            writeln!(formatted_code)?;
111	        }
112	
113	        for comment in comments_iter {
114	            let newlines = collect_newlines_after_comment(&formatter.comments_context, comment);
115	
116	            match comment.comment_kind {
117	                CommentKind::Newlined => {
118	                    write!(
119	                        formatted_code,
120	                        "{}{}{}",
121	                        formatter.indent_to_str()?,
122	                        comment.span().as_str(),
123	                        newlines
124	                    )?;
125	                }
126	                CommentKind::Trailing => {
127	                    write_trailing_comment(formatted_code, comment)?;
128	                }
129	                CommentKind::Inlined => {
130	                    // We do a trim and truncate here to ensure that only a single whitespace separates
131	                    // the inlined comment from the previous token.
132	                    formatted_code.truncate(formatted_code.trim_end().len());
133	                    write!(formatted_code, " {} ", comment.span().as_str())?;
134	                }
135	                CommentKind::Multilined => {
136	                    write!(
137	                        formatted_code,
138	                        "{}{}",
139	                        formatter.indent_to_str()?,
140	                        comment.span().as_str(),
141	                    )?;
142	                }
143	            }
144	        }
145	    }
146	
147	    // Keep comments that are NOT within `range` within the CommentMap.
148	    // This is destructive behavior for comments since if any steps above fail
149	    // and comments were not written, `retains()` will still delete these comments.
150	    formatter
151	        .comments_context
152	        .map
153	        .retain(|bs, _| !bs.contained_within(&range));
154	
155	    Ok(true)
156	}
