19	/// A stripped down version of sway-types::src::Span
20	#[derive(Eq, PartialEq, Debug, Clone, Default)]
21	pub struct ByteSpan {
22	    // The byte position in the string of the start of the span.
23	    pub start: usize,
24	    // The byte position in the string of the end of the span.
25	    pub end: usize,
26	}
27	
28	impl From<Span> for ByteSpan {
29	    /// Takes `start` and `end` from `sway::types::Span` and constructs a `ByteSpan`
30	    fn from(span: Span) -> Self {
31	        ByteSpan {
32	            start: span.start(),
33	            end: span.end(),
34	        }
35	    }
36	}
37	
38	impl ByteSpan {
39	    pub fn len(&self) -> usize {
40	        self.end - self.start
41	    }
42	
43	    /// Checks that the ByteSpan referenced by Self is encapsulated by a given Range<usize>.
44	    /// This range is inclusive to account for the start and end of the file.
45	    pub fn contained_within(&self, range: &Range<usize>) -> bool {
46	        range.start <= self.start && self.end <= range.end
47	    }
48	}
49	
50	impl Ord for ByteSpan {
51	    fn cmp(&self, other: &Self) -> Ordering {
52	        // If the starting position is the same encapsulating span (i.e, wider one) should come
53	        // first.
54	        match self.start.cmp(&other.start) {
55	            Ordering::Equal => other.end.cmp(&self.end),
56	            ord => ord,
57	        }
58	    }
59	}
