13	impl Format for CodeBlockContents {
14	    fn format(
15	        &self,
16	        formatted_code: &mut FormattedCode,
17	        formatter: &mut Formatter,
18	    ) -> Result<(), FormatterError> {
19	        if !self.statements.is_empty() || self.final_expr_opt.is_some() {
20	            match formatter.shape.code_line.line_style {
21	                LineStyle::Inline => {
22	                    write!(formatted_code, " ")?;
23	                    for statement in self.statements.iter() {
24	                        statement.format(formatted_code, formatter)?;
25	                    }
26	                    if let Some(final_expr) = &self.final_expr_opt {
27	                        final_expr.format(formatted_code, formatter)?;
28	                    }
29	                    write!(formatted_code, " ")?;
30	                }
31	                _ => {
32	                    writeln!(formatted_code)?;
33	                    for statement in self.statements.iter() {
34	                        write!(formatted_code, "{}", formatter.indent_to_str()?)?;
35	                        statement.format(formatted_code, formatter)?;
36	                        if !formatted_code.ends_with('\n') {
37	                            writeln!(formatted_code)?;
38	                        }
39	                    }
40	                    if let Some(final_expr) = &self.final_expr_opt {
41	                        write!(formatted_code, "{}", formatter.indent_to_str()?)?;
42	                        final_expr.format(formatted_code, formatter)?;
43	                        writeln!(formatted_code)?;
44	                    }
45	                }
46	            }
47	        } else {
48	            let comments: bool = write_comments(
49	                formatted_code,
50	                self.span().start()..self.span().end(),
51	                formatter,
52	            )?;
53	            if !comments {
54	                formatter.shape.block_unindent(&formatter.config);
55	            }
56	        }
57	
58	        Ok(())
59	    }
60	}
